// Seed the 100-popular pass: adds references that a watch audience would
// expect to find in a real register, with a story for the Casio entries
// and provenance where the year or movement name is itself a marker.
// Idempotent on card id (existing card file is left alone).

import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'

const ROOT = new URL('..', import.meta.url).pathname
const CARD_DIR = join(ROOT, 'data/cards')

// Date stamp used across all new provenance events
const DATE = '2026-08-03'

// Card factory — every field is mandatory except comps and provenance.
// - id:           filename without .json
// - brand:        display brand (must match BRAND_REGION keys)
// - reference:    official alphanumeric reference
// - name:         official model name
// - nickname:     community name, null if none
// - collection:   model family
// - tier:         trinity | crown | haute | core | attainable
// - start_year:   production start
// - end_year:     production end, null if current
// - discontinued: boolean
// - caliber:      manufacturer caliber code
// - type:         movement type
// - mm:           case diameter
// - material:     case material
// - bezel:        bezel description
// - msrp_usd:     launch price, USD
// - msrp_year:    launch year for the MSRP entry
// - msrp_url:     source URL for the MSRP
// - one_liner:    one factual sentence
// - story:        2-4 sentences; no marketing fluff
// - starter_alt:  id of an attainable-tier card with similar DNA
// - provs:        optional array of provenance events
// - comps:        optional array of comps (USD only, real sold prices)
function make(c) {
  return {
    schema_version: 1,
    id: c.id,
    identity: {
      brand: c.brand,
      reference: c.reference,
      name: c.name,
      nickname: c.nickname ?? null,
      collection: c.collection,
      tier: c.tier,
      produced: { start_year: c.start_year, end_year: c.end_year ?? null, discontinued: !!c.discontinued },
      movement: { caliber: c.caliber, type: c.type },
      case: { diameter_mm: c.mm, material: c.material, bezel: c.bezel },
      one_liner: c.one_liner,
    },
    retail: {
      msrp_history: [{ effective_year: c.msrp_year, price_usd: c.msrp_usd, source_url: c.msrp_url }],
      current_msrp_usd: c.discontinued ? null : c.msrp_usd,
    },
    market_evidence: { comps: c.comps ?? [], listing_observations: [] },
    scarcity_inputs: {
      brand_production_est: null,
      limited_edition: { is_limited: false, stated_size: null, source_url: null },
      waitlist_evidence: [],
      auction_appearances_5y: null,
    },
    provenance_events: c.provs ?? [],
    narrative: {
      story: c.story,
      collector_notes: c.collector_notes ?? '',
      starter_alternative: c.starter_alt ?? null,
    },
    meta: { curated_by: 'agent-popular-100', curated_date: DATE, sources: [c.msrp_url].filter(Boolean) },
  }
}

