// ─── Write the cards ───────────────────────────────────────────────────────
const ALL = [...TRINITY, ...CROWN, ...HAUTE, ...CORE, ...ATTAINABLE]

let added = 0
let skipped = 0
for (const card of ALL) {
  const file = join(CARD_DIR, card.id + '.json')
  if (existsSync(file)) { skipped++; continue }
  writeFileSync(file, JSON.stringify(card, null, 2) + '\n')
  added++
}
console.log(`✓ Wrote ${added} new popular-100 cards; skipped ${skipped} (already on disk)`)
console.log(`Tiers: trinity=${TRINITY.length} crown=${CROWN.length} haute=${HAUTE.length} core=${CORE.length} attainable=${ATTAINABLE.length} (total ${ALL.length})`)
